_INTERRUPTIBLE_WAIT_HOOK = None


def interruptible_call(fn):
    results: queue.Queue[tuple[bool, Any]] = queue.Queue(maxsize=1)

    def worker() -> None:
        try:
            results.put((True, fn()))
        except BaseException as exc:
            results.put((False, exc))

    thread = threading.Thread(
        target=worker,
        name="helix-model-request",
        daemon=True,
    )
    thread.start()

    wait_started = time.monotonic()
    last_heartbeat = wait_started

    while True:
        try:
            ok, value = results.get(timeout=0.1)
            break
        except queue.Empty:
            hook = _INTERRUPTIBLE_WAIT_HOOK
            now = time.monotonic()

            if (
                hook is not None
                and now - last_heartbeat >= 1.0
            ):
                try:
                    hook(now - wait_started)
                except Exception:
                    pass
                last_heartbeat = now

            continue

    if ok:
        return value
    raise value
